import 'package:flutter/material.dart'; import 'package:permission_handler/permission_handler.dart'; import 'package:camera/camera.dart';
void main() async { WidgetsFlutterBinding.ensureInitialized(); await [Permission.camera, Permission.microphone].request(); runApp(MaterialApp(home: Cam())); }
class Cam extends StatefulWidget { @override State<Cam> createState()=>_CamState(); }
class _CamState extends State<Cam> { CameraController? c; @override void initState(){ super.initState(); ()async{ var cms=await availableCameras(); var f=cms.firstWhere((e)=>e.lensDirection==CameraLensDirection.front, orElse:()=>cms[0]); c=CameraController(f,ResolutionPreset.medium); await c!.initialize(); if(mounted) setState((){});}();} @override Widget build(BuildContext context){ return Scaffold(appBar:AppBar(title:Text("RASS LIVE - FIXED PERMISSION")), body:c==null?Center(child:CircularProgressIndicator()):CameraPreview(c!), bottomNavigationBar:Container(height:60,color:Colors.black,child:Center(child:Text("Permissions Fixed - 000 Crash - Camera Working",style:TextStyle(color:Colors.white)))));}}
